<div class="admin-heading"><div><span>CRM المصغر</span><h1>العملاء المحتملون</h1></div><div class="filters"><a href="/admin/leads">الكل</a><a href="/admin/leads?status=new">جديد</a><a href="/admin/leads?status=interested">مهتم</a><a href="/admin/leads?status=quotation">عرض سعر</a><a href="/admin/leads?status=won">تم التعاقد</a></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>رقم الطلب</th><th>العميل</th><th>الخدمة</th><th>المصدر</th><th>الحالة</th><th>التاريخ</th></tr></thead><tbody><?php foreach($leads as $l):?><tr><td><code><?= e($l['lead_id']) ?></code></td><td><b><?= e($l['name']) ?></b><small><a href="tel:<?= e($l['phone']) ?>"><?= e($l['phone']) ?></a></small></td><td><?= e($l['service']) ?></td><td><?= e($l['utm_source'] ?: 'مباشر') ?></td><td><form method="post" action="/admin/leads/<?= (int)$l['id'] ?>/status" class="inline-status"><?= csrf_field() ?><select name="status" data-status-select><?php foreach(['new'=>'جديد','contacted'=>'تم التواصل','interested'=>'مهتم','quotation'=>'عرض سعر','won'=>'تم التعاقد','lost'=>'غير مناسب'] as $k=>$v):?><option value="<?= $k ?>" <?= $l['status']===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></form></td><td><?= e($l['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$leads):?><tr><td colspan="6" class="empty">لا توجد طلبات مطابقة.</td></tr><?php endif; ?></tbody></table></div></section>